"use strict";(globalThis.webpackChunkgrc||=[]).push([[43433],{75532(e,a,r){r.r(a),r.d(a,{default:()=>l,metadata:()=>n});var n=r(48233),t=r(74848),s=r(28453);const i={authorsImageUrls:[void 0]};function o(e){const a={a:"a",h2:"h2",li:"li",p:"p",ul:"ul",...(0,s.R)(),...e.components};return(0,t.jsxs)(t.Fragment,{children:[(0,t.jsx)(a.p,{children:'Xian-He Sun gave a plenary keynote, "High Performance Data Access: the DMSH approach", at the National Annual Conference on High Performance Computing (HPC China 2019) in Hohhot, China, on August 22, 2019. The talk followed the memory wall down to storage and presented Hermes, GRC\'s system for buffering data across a deep memory and storage hierarchy (DMSH).'}),"\n","\n",(0,t.jsx)(a.h2,{id:"from-the-memory-wall-to-the-io-wall",children:"From the memory wall to the I/O wall"}),"\n",(0,t.jsx)(a.p,{children:"The talk opened with the trend lines behind Sun's earlier work on memory-bounded speedup (1990) and the memory wall (1994). Processor performance grew about 52% a year until 2004, and multi-core processors have pushed aggregate performance higher since. Memory performance grew about 9% a year and I/O about 6%. The gap between processors and storage keeps widening, so I/O has become the bottleneck of HPC. Parallel I/O systems, which stripe data across many file servers, help but are not enough."}),"\n",(0,t.jsx)(a.h2,{id:"a-deep-memory-and-storage-hierarchy",children:"A deep memory and storage hierarchy"}),"\n",(0,t.jsx)(a.p,{children:"HPC sites have begun installing new layers between memory and the parallel file system. One example in the talk was Cori, a Cray XC40 at NERSC that uses Cray's DataWarp burst buffer. New non-volatile memory devices and remote data access methods add further layers. Together they form a DMSH, a multi-level hierarchy in which a layer does not have to hold a copy of the data in the layer below."}),"\n",(0,t.jsx)(a.p,{children:"The slides listed what was missing to use such a hierarchy well: software that manages heterogeneous tiers as a whole, intelligent placement of data among the tiers, automatic movement of data between them, native buffering support in HDF5, and the expertise that most users do not have. The stated goal was for the layers to be invisible to applications, with no loss of I/O performance."}),"\n",(0,t.jsx)(a.h2,{id:"hermes",children:"Hermes"}),"\n",(0,t.jsx)(a.p,{children:"Sun's answer was to combine DMSH buffering with the HDF5 data format, which already carries rich information about the data it stores. Hermes, built with The HDF Group under an NSF grant, is a multi-tiered, distributed buffering platform. Its machine model has four layers: RAM, local NVMe or SSD, shared burst buffers and a remote parallel file system. Data moves vertically through the layers within a node and horizontally across nodes. Hermes components include a data placement engine that chooses a tier for each piece of data, a data organizer that carries out prefetching and eviction, a metadata manager, a cache manager with several replacement policies, and an application orchestrator that limits interference between applications sharing a tier."}),"\n",(0,t.jsx)(a.p,{children:"The design drew on GRC papers from 2018: Hermes at ACM HPDC, IRIS at ACM ICS and the Harmonia I/O scheduler at IEEE Cluster, all by Anthony Kougkas, Hariharan Devarajan and Sun, with Jay Lofstead on Harmonia."}),"\n",(0,t.jsx)(a.h2,{id:"learn-more",children:"Learn more"}),"\n",(0,t.jsxs)(a.ul,{children:["\n",(0,t.jsx)(a.li,{children:(0,t.jsx)(a.a,{href:"http://www.cs.iit.edu/~scs/assets/files/Hermes-hpc-china.pdf",children:"Keynote slides (PDF)"})}),"\n",(0,t.jsx)(a.li,{children:(0,t.jsx)(a.a,{href:"http://web.archive.org/web/2019/http://hpcchina2019.csp.escience.cn:80/dct/page/70029",children:"HPC China 2019 program (Internet Archive copy)"})}),"\n",(0,t.jsx)(a.li,{children:(0,t.jsx)(a.a,{href:"/gnosis/publications/kougkas-2018-hermes-25f4/",children:"Hermes: A Heterogeneous-Aware Multi-Tiered Distributed I/O Buffering System (HPDC 2018)"})}),"\n",(0,t.jsx)(a.li,{children:(0,t.jsx)(a.a,{href:"/gnosis/publications/kougkas-2018-iris-f1a6/",children:"IRIS: I/O Redirection via Integrated Storage (ICS 2018)"})}),"\n",(0,t.jsx)(a.li,{children:(0,t.jsx)(a.a,{href:"/gnosis/publications/kougkas-2018-harmonia-5ca9/",children:"Harmonia: An Interference-Aware Dynamic I/O Scheduler (Cluster 2018)"})}),"\n",(0,t.jsx)(a.li,{children:(0,t.jsx)(a.a,{href:"/research/projects/hermes/",children:"Hermes project page"})}),"\n",(0,t.jsx)(a.li,{children:(0,t.jsx)(a.a,{href:"/center/team/xian-he-sun/",children:"Xian-He Sun's profile"})}),"\n"]})]})}function l(e={}){const{wrapper:a}={...(0,s.R)(),...e.components};return a?(0,t.jsx)(a,{...e,children:(0,t.jsx)(o,{...e})}):o(e)}r.d(a,["assets",0,i,"contentTitle",0,undefined,"frontMatter",0,{title:"HPC China 2019 keynote: high performance data access",description:"At HPC China 2019 in Hohhot, Xian-He Sun traced the memory wall down to I/O and presented Hermes, which buffers data across a deep memory and storage hierarchy.",authors:"grc",tags:["knowledge-sharing","Keynote","HPC China","Data buffering","HDF5","Hermes"],image:"/img/members/sun.webp"},"toc",0,[{value:"From the memory wall to the I/O wall",id:"from-the-memory-wall-to-the-io-wall",level:2},{value:"A deep memory and storage hierarchy",id:"a-deep-memory-and-storage-hierarchy",level:2},{value:"Hermes",id:"hermes",level:2},{value:"Learn more",id:"learn-more",level:2}]])},28453(e,a,r){r.d(a,{R:()=>i,x:()=>o});var n=r(96540);const t={},s=n.createContext(t);function i(e){const a=n.useContext(s);return n.useMemo((function(){return"function"==typeof e?e(a):{...a,...e}}),[a,e])}function o(e){let a;return a=e.disableParentContext?"function"==typeof e.components?e.components(t):e.components||t:i(e.components),n.createElement(s.Provider,{value:a},e.children)}},48233(e){e.exports=JSON.parse('{"permalink":"/gnosis/articles/2019/08/22/sun-hpcchina-keynote","source":"@site/blog/2019-08-22-sun-hpcchina-keynote.mdx","title":"HPC China 2019 keynote: high performance data access","description":"At HPC China 2019 in Hohhot, Xian-He Sun traced the memory wall down to I/O and presented Hermes, which buffers data across a deep memory and storage hierarchy.","date":"2019-08-22T00:00:00.000Z","tags":[{"inline":true,"label":"knowledge-sharing","permalink":"/gnosis/articles/tags/knowledge-sharing"},{"inline":true,"label":"Keynote","permalink":"/gnosis/articles/tags/keynote"},{"inline":true,"label":"HPC China","permalink":"/gnosis/articles/tags/hpc-china"},{"inline":true,"label":"Data buffering","permalink":"/gnosis/articles/tags/data-buffering"},{"inline":true,"label":"HDF5","permalink":"/gnosis/articles/tags/hdf-5"},{"inline":true,"label":"Hermes","permalink":"/gnosis/articles/tags/hermes"}],"readingTime":2.76,"hasTruncateMarker":true,"authors":[{"name":"Gnosis Research Center","url":"https://grc.iit.edu","imageURL":"/img/logo.png","key":"grc","page":null}],"frontMatter":{"title":"HPC China 2019 keynote: high performance data access","description":"At HPC China 2019 in Hohhot, Xian-He Sun traced the memory wall down to I/O and presented Hermes, which buffers data across a deep memory and storage hierarchy.","authors":"grc","tags":["knowledge-sharing","Keynote","HPC China","Data buffering","HDF5","Hermes"],"image":"/img/members/sun.webp"},"unlisted":false,"prevItem":{"title":"HPBD&IS 2020 keynote: label-based data representation for big data I/O","permalink":"/gnosis/articles/2020/05/23/sun-hpbdis-keynote"},"nextItem":{"title":"LABIOS receives the Karsten Schwan Best Paper Award at HPDC 2019","permalink":"/gnosis/articles/2019/06/24/labios-best-paper"}}')}}]);